export interface VideoFile {
  file: File;
  previewUrl: string;
  base64Data?: string;
  mimeType: string;
}

export enum ProcessingStatus {
  IDLE = 'IDLE',
  READING_FILE = 'READING_FILE',
  ANALYZING = 'ANALYZING', // Gemini is thinking
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface SubtitleResponse {
  rawSrt: string;
  filename: string;
}

import { GoogleGenAI } from "@google/genai";

// Initialize the client
// The API key is injected via process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates an SRT subtitle string from a video file.
 * Uses gemini-3-pro-preview for multimodal video understanding.
 */
export const generateSubtitlesFromVideo = async (
  base64Data: string, 
  mimeType: string
): Promise<string> => {

  try {
    const modelId = 'gemini-3-pro-preview';

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Data,
              mimeType: mimeType,
            },
          },
          {
            text: `You are an expert professional video subtitler. 

            Your task is to analyze the provided video and generate a precise SubRip Subtitle (SRT) file.

            1. Transcribe all spoken dialogue accurately.
            2. Identify speaker changes if relevant (e.g., "Speaker 1:", "Narrator:").
            3. CRITICAL: Because you have video understanding capabilities, include significant visual context or non-speech audio cues in brackets, for example: [Door slams], [Upbeat music plays], [Character smiles nervously], [Explosion].
            4. Ensure the timestamps are strictly in the SRT format (00:00:00,000 --> 00:00:00,000).
            5. Return ONLY the raw SRT content. Do not wrap it in markdown code blocks like \`\`\`srt ... \`\`\`. Do not add any introductory text. Just the file content.`
          },
        ],
      },
      config: {
        // High token limit to allow for long subtitle files
        maxOutputTokens: 8192, 
        temperature: 0.2, // Lower temperature for more factual transcription
      }
    });

    const srtContent = response.text || "";

    // Cleanup potential markdown formatting if the model disobeys slightly
    const cleanSrt = srtContent.replace(/^```srt\n/, '').replace(/^```\n/, '').replace(/\n```$/, '');

    return cleanSrt;

  } catch (error) {
    console.error("Error generating subtitles:", error);
    throw error;
  }
};

import React, { useCallback, useRef, useState } from 'react';
import { Upload, X, FileVideo } from 'lucide-react';
import { VideoFile } from '../types';

interface VideoUploaderProps {
  onVideoSelected: (video: VideoFile) => void;
  onClear: () => void;
  selectedVideo: VideoFile | null;
  disabled?: boolean;
}

export const VideoUploader: React.FC<VideoUploaderProps> = ({ 
  onVideoSelected, 
  onClear, 
  selectedVideo,
  disabled 
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFile = useCallback((file: File) => {
    if (!file.type.startsWith('video/')) {
      alert('Please upload a valid video file.');
      return;
    }

    // Limit file size for this demo to prevent browser crash on Base64 conversion
    // 50MB limit
    if (file.size > 50 * 1024 * 1024) {
      alert('File is too large for this demo. Please upload a video smaller than 50MB.');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const result = e.target?.result as string;
      // Extract base64 part (remove data:video/mp4;base64, prefix)
      const base64Data = result.split(',')[1];

      onVideoSelected({
        file,
        previewUrl: URL.createObjectURL(file),
        base64Data,
        mimeType: file.type
      });
    };
    reader.readAsDataURL(file);
  }, [onVideoSelected]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  if (selectedVideo) {
    return (
      <div className="w-full relative rounded-xl overflow-hidden border border-slate-700 bg-slate-800/50 shadow-xl">
        <video 
          src={selectedVideo.previewUrl} 
          controls 
          className="w-full max-h-[400px] object-contain bg-black"
        />
        <div className="p-4 flex justify-between items-center border-t border-slate-700">
          <div className="flex items-center space-x-2 text-slate-300">
            <FileVideo className="w-5 h-5 text-indigo-400" />
            <span className="text-sm font-medium truncate max-w-[200px]">{selectedVideo.file.name}</span>
            <span className="text-xs text-slate-500">({(selectedVideo.file.size / (1024 * 1024)).toFixed(2)} MB)</span>
          </div>
          {!disabled && (
            <button 
              onClick={onClear}
              className="p-2 hover:bg-red-500/20 text-red-400 rounded-full transition-colors"
              title="Remove video"
            >
              <X className="w-5 h-5" />
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div
      onDrop={handleDrop}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onClick={() => !disabled && fileInputRef.current?.click()}
      className={`
        w-full h-64 border-2 border-dashed rounded-xl flex flex-col items-center justify-center cursor-pointer transition-all duration-300
        ${isDragging 
          ? 'border-indigo-500 bg-indigo-500/10 scale-[1.02]' 
          : 'border-slate-600 hover:border-indigo-400 hover:bg-slate-800/50 bg-slate-800/20'}
        ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
      `}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleChange} 
        accept="video/*" 
        className="hidden" 
        disabled={disabled}
      />

      <div className="bg-slate-800 p-4 rounded-full mb-4 shadow-lg ring-1 ring-white/10">
        <Upload className={`w-8 h-8 ${isDragging ? 'text-indigo-400' : 'text-slate-400'}`} />
      </div>

      <p className="text-lg font-medium text-slate-200 mb-2">
        {isDragging ? 'Drop video here' : 'Click or Drag video here'}
      </p>
      <p className="text-sm text-slate-500 max-w-xs text-center">
        Supports MP4, MOV, WebM (Max 50MB)
      </p>
    </div>
  );
};

import React, { useRef } from 'react';
import { Download, Copy, Check } from 'lucide-react';

interface SubtitleDisplayProps {
  srtContent: string;
  filename?: string;
}

export const SubtitleDisplay: React.FC<SubtitleDisplayProps> = ({ srtContent, filename = "subtitles" }) => {
  const [copied, setCopied] = React.useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleDownload = () => {
    const blob = new Blob([srtContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    // Ensure filename ends in .srt
    const safeFilename = filename.replace(/\.[^/.]+$/, "").replace(/\s+/g, "_");
    link.download = `${safeFilename}.srt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(srtContent).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  return (
    <div className="w-full flex flex-col space-y-3 animate-fade-in-up">
      <div className="flex justify-between items-center">
        <h3 className="text-lg font-semibold text-white">Generated Subtitles (SRT)</h3>
        <div className="flex space-x-2">
          <button
            onClick={handleCopy}
            className="flex items-center space-x-1.5 px-3 py-1.5 text-xs font-medium text-slate-300 bg-slate-800 hover:bg-slate-700 rounded-lg border border-slate-600 transition-colors"
          >
            {copied ? <Check className="w-3.5 h-3.5 text-green-400" /> : <Copy className="w-3.5 h-3.5" />}
            <span>{copied ? 'Copied' : 'Copy'}</span>
          </button>
          <button
            onClick={handleDownload}
            className="flex items-center space-x-1.5 px-3 py-1.5 text-xs font-medium text-white bg-indigo-600 hover:bg-indigo-500 rounded-lg shadow-lg shadow-indigo-500/20 transition-all hover:scale-105"
          >
            <Download className="w-3.5 h-3.5" />
            <span>Download .srt</span>
          </button>
        </div>
      </div>

      <div className="relative">
        <textarea
          ref={textareaRef}
          readOnly
          value={srtContent}
          className="w-full h-80 bg-slate-900 border border-slate-700 rounded-xl p-4 text-sm font-mono text-slate-300 focus:ring-2 focus:ring-indigo-500 focus:outline-none resize-none leading-relaxed"
          placeholder="Subtitles will appear here..."
        />
        <div className="absolute top-2 right-4 text-xs text-slate-600 font-mono">
           SRT Format
        </div>
      </div>
    </div>
  );
};

